      children: ["\n", (0,jsx_runtime.jsx)(_components.p, {
        children: "कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा |\r\nकच्चिदज्ञानसम्मोहः प्रनष्टस्ते धनञ्जय"
      }), "\n"]
